#!/usr/bin/env node
/**
 * scripts/gen-types.js
 *
 * Generates TypeScript types from the linked Supabase project and writes
 * them to src/db/supabase.types.ts (for use in the sync engine).
 *
 * Requires the Supabase CLI to be installed and the project to be linked
 * (`npx supabase link --project-ref <ref>`).
 *
 * Usage:
 *   node scripts/gen-types.js
 *   npm run gen-types           (via package.json "scripts")
 *
 * The generated file is intentionally kept out of version control — add
 * src/db/supabase.types.ts to .gitignore if you prefer auto-generating it
 * in CI. For now it is committed so the team can use it without the CLI.
 */

const { spawnSync } = require('child_process');
const path = require('path');

const OUT = path.join(__dirname, '..', 'src', 'db', 'supabase.types.ts');

console.log('Generating Supabase TypeScript types …');
console.log(`Output: ${OUT}\n`);

const result = spawnSync(
  'npx',
  ['supabase', 'gen', 'types', 'typescript', '--linked', '--schema', 'public'],
  { stdio: ['inherit', 'pipe', 'inherit'], shell: true }
);

if (result.status !== 0) {
  console.error(
    '✗  supabase gen types failed.\n' +
    '   Make sure the Supabase CLI is installed and the project is linked:\n' +
    '     npx supabase login\n' +
    '     npx supabase link --project-ref <your-project-ref>'
  );
  process.exit(1);
}

const { writeFileSync } = require('fs');
const header =
  '// AUTO-GENERATED by scripts/gen-types.js — do not edit by hand.\n' +
  '// Run `npm run gen-types` to refresh after a schema migration.\n\n';

writeFileSync(OUT, header + result.stdout.toString());
console.log('✓  Types written to src/db/supabase.types.ts');

